/* Dino Dominion Build 5.18 — curated Royal Messenger stickers and original GIF reactions.
 * Content is self-contained: no third-party GIF API, no image uploads, no external links.
 * Media is represented by a short, whitelisted marker in existing chat body fields.
 * Copyright: original Dino Dominion reaction art/animation generated for this build.
 */
(()=>{'use strict';
const PACK={"stickers":[{"id":"rex-roar","title":"REX ROAR","emoji":"🦖","accent":"#79b89f","dark":"#132e35"},{"id":"welcome","title":"WELCOME","emoji":"👋","accent":"#e0b876","dark":"#38341c"},{"id":"alliance","title":"ALLIANCE","emoji":"🛡️","accent":"#a9c9b8","dark":"#163c43"},{"id":"good-game","title":"GOOD GAME","emoji":"🤝","accent":"#8acfe4","dark":"#1d354e"},{"id":"heart","title":"RESPECT","emoji":"❤️","accent":"#dba78d","dark":"#442b31"},{"id":"victory","title":"VICTORY","emoji":"👑","accent":"#efd08a","dark":"#413821"},{"id":"charge","title":"CHARGE!","emoji":"⚔️","accent":"#e99d75","dark":"#493022"},{"id":"chill","title":"REST DAY","emoji":"🦕","accent":"#95c8a9","dark":"#263e2f"}],"gifs":{"roar":"","victory":"","charge":"","gg":""},"gifLabels":{"roar":"ROAR!","victory":"VICTORY!","charge":"CHARGE!","gg":"GOOD GAME!"}};
const STICKERS=new Map(PACK.stickers.map(s=>[s.id,s]));
const GIFS=new Map(Object.entries(PACK.gifs));
const PATTERN=/^\[\[DD518:(STICKER|GIF):([a-z0-9-]{1,32})\]\]$/;
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
let tray=null,tab=null;
const stCache=new Map();
function valid(body){const m=PATTERN.exec(String(body||''));if(!m)return null;if(m[1]==='STICKER'&&STICKERS.has(m[2]))return {kind:'sticker',id:m[2]};if(m[1]==='GIF'&&GIFS.has(m[2]))return {kind:'gif',id:m[2]};return null;}
function stickerSvg(s){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 192" role="img" aria-label="${s.title}"><defs><radialGradient id="bg"><stop stop-color="${s.dark}"/><stop offset="1" stop-color="#0b1c26"/></radialGradient><linearGradient id="shine" x2=".8" y2="1"><stop stop-color="${s.accent}"/><stop offset="1" stop-color="#a58351"/></linearGradient></defs><rect x="4" y="4" width="232" height="184" rx="25" fill="url(#bg)" stroke="${s.accent}" stroke-width="3"/><path d="M16 155 Q120 120 224 155" stroke="${s.accent}" opacity=".24" stroke-width="2" fill="none"/><circle cx="120" cy="79" r="55" stroke="url(#shine)" fill="none" stroke-width="2" opacity=".7"/><circle cx="120" cy="79" r="48" fill="${s.accent}" opacity=".10"/><text x="120" y="104" text-anchor="middle" font-size="62" font-family="system-ui,Arial">${s.emoji}</text><rect x="36" y="139" width="168" height="31" rx="8" fill="#0c222b" stroke="${s.accent}" stroke-width="1"/><text x="120" y="160" text-anchor="middle" font-size="17" font-family="Arial,sans-serif" font-weight="800" letter-spacing="1" fill="#f7e6c2">${s.title}</text></svg>`;}
function srcFor(kind,id){if(kind==='gif')return 'data:image/gif;base64,'+GIFS.get(id);let cached=stCache.get(id);if(cached)return cached;const s=STICKERS.get(id);if(!s)return '';cached='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(stickerSvg(s));stCache.set(id,cached);return cached;}
function labelFor(body){const item=valid(body);if(!item)return null;const label=item.kind==='gif'?PACK.gifLabels[item.id]:STICKERS.get(item.id).title;return (item.kind==='gif'?'🎞️ GIF: ':'🧩 Sticker: ')+label;}
function renderBody(body){const item=valid(body);if(!item)return null;const label=labelFor(body);return `<span class="dd518Media" aria-label="${esc(label)}"><img src="${srcFor(item.kind,item.id)}" loading="lazy" draggable="false" alt="${esc(label)}" width="220" height="170"><span class="dd518Alt">${esc(label)}</span></span>`;}
function choices(kind){return kind==='sticker'?PACK.stickers.map(s=>({id:s.id,title:s.title,src:srcFor('sticker',s.id)})):[...GIFS.keys()].map(id=>({id,title:PACK.gifLabels[id],src:srcFor('gif',id)}));}
function renderTray(){if(!tray)return;tray.hidden=!tab;if(!tab){tray.innerHTML='';return;}const items=choices(tab);tray.innerHTML=`<div class="dd518TrayHeader"><strong>${tab==='sticker'?'🧩 Kingdom Stickers':'🎞️ Dino GIF Reactions'}</strong><span>${tab==='sticker'?'Original in-game stickers':'Curated animated reactions'}</span><button type="button" data-dd518-close aria-label="Close media picker">✕</button></div><div class="dd518Grid">${items.map(s=>`<button type="button" data-dd518-send="${tab}:${s.id}" aria-label="Send ${esc(s.title)}" title="${esc(s.title)}"><img src="${s.src}" width="100" height="80" alt=""><small>${esc(s.title)}</small></button>`).join('')}</div><p class="dd518Safety">🔒 Only curated reactions can be sent. Personal photo and GIF uploads are not enabled.</p>`;}
function openPicker(which){tab=tab===which?null:which;const ep=$('dd517Emoji');if(ep)ep.hidden=true;renderTray();tray?.querySelector('button[data-dd518-send]')?.focus({preventScroll:true});}
async function sendItem(which,id){if(!tray||!PACK||!(which==='sticker'?STICKERS.has(id):which==='gif'&&GIFS.has(id)))return;
 const token=`[[DD518:${which.toUpperCase()}:${id}]]`;
 const success=await window.DD517?.sendRich?.(token);
 if(success){tab=null;renderTray();} else {
  const status=$('dd517Status');if(status&&!status.textContent) {status.textContent='Send your draft first, or wait a moment before sending another reaction.';status.hidden=false;}
 }
}
function init(){const root=$('dd517Messenger'),form=$('dd517Form'),composer=root?.querySelector('.dd517Composer');if(!root||!form||!composer)return;
 const emoji=form.querySelector('[data-517="emoji"]');if(!emoji)return;
 const st=document.createElement('button');st.type='button';st.className='dd518PickerBtn';st.setAttribute('aria-label','Open dinosaur stickers');st.title='Stickers';st.dataset.dd518Picker='sticker';st.textContent='🧩';
 const gf=document.createElement('button');gf.type='button';gf.className='dd518PickerBtn';gf.setAttribute('aria-label','Open GIF reactions');gf.title='GIFs';gf.dataset.dd518Picker='gif';gf.textContent='🎞️';
 emoji.insertAdjacentElement('afterend',gf);emoji.insertAdjacentElement('afterend',st);
 tray=document.createElement('div');tray.id='dd518Tray';tray.className='dd518Tray';tray.hidden=true;tray.setAttribute('aria-label','Choose a sticker or GIF');composer.insertBefore(tray,form);
 const hint=$('dd517ComposerHint');if(hint)hint.textContent='Emoji, Dino stickers & curated GIFs · Report abusive messages · No photo uploads yet.';
 root.addEventListener('click',async ev=>{const btn=ev.target.closest('[data-dd518-picker],[data-dd518-send],[data-dd518-close]');if(!btn||!root.contains(btn))return;ev.preventDefault();ev.stopPropagation();if(btn.dataset.dd518Picker){openPicker(btn.dataset.dd518Picker);return;}if(btn.hasAttribute('data-dd518-close')){tab=null;renderTray();return;}
 const parts=String(btn.dataset.dd518Send||'').split(':');if(parts.length===2)await sendItem(parts[0],parts[1]);});
 const escListener=e=>{if(e.key==='Escape'&&tab){e.stopPropagation();tab=null;renderTray();}};root.addEventListener('keydown',escListener);
}
window.DD518={version:'5.18.0-beta.1',isMedia:body=>!!valid(body),labelFor,renderBody,stickerIds:[...STICKERS.keys()],gifIds:[...GIFS.keys()]};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
